<script lang="ts">
  import { onMount, onDestroy, untrack } from 'svelte';
  import { invoke } from '@tauri-apps/api/core';
  import { openUrl } from '@tauri-apps/plugin-opener';
  import { isGameRunning } from './game_session';
  import UiIcon from './UiIcon.svelte';
  import GameIcon from './GameIcon.svelte';
  import ServerMotd from './ServerMotd.svelte';
  import { DIRECTORY_MODES, addressKey, directoryPages, directoryTimestamp, type DirectoryEntry, type DirectoryPage } from './server_directory';
  import type { LiveServerStatus } from './server_live';
  let {savedAddresses=[],busy=false,currentVersion='',onadd,onjoin}:{savedAddresses?:string[];busy?:boolean;currentVersion?:string;onadd:(entry:DirectoryEntry)=>Promise<boolean>;onjoin:(address:string)=>void|Promise<void>}=$props();
  type Config={configured:boolean;base_url:string;publishing_available:boolean};
  type Latency={address:string;latency_ms:number;quality:'good'|'fair'|'poor';checked_at:number};
  let config=$state<Config>({configured:false,base_url:'',publishing_available:false});
  let searchInput=$state(''),search=$state(''),versionInput=$state(''),version=$state('');
  let mode=$state(''),language=$state(''),region=$state(''),sort=$state('players'),page=$state(1);
  let remote=$state<DirectoryPage|null>(null),loading=$state(false),error=$state(''),notice=$state(''),adding=$state('');
  let pinging=$state<Record<string,boolean>>({}),latencies=$state<Record<string,Latency>>({}),foreground=$state(true);
  let publishing=$state(false),publishOpen=$state(false),publishName=$state(''),publishAddress=$state(''),publishCategory=$state('Survival'),publishRegion=$state('Global'),publishLanguage=$state('ES');
  let jumpPage=$state(1);let request=0,disposed=false;let debounce:ReturnType<typeof setTimeout>|undefined;
  let saved=$derived(new Set(savedAddresses.map(addressKey)));
  let total=$derived(remote?.total??0);
  let pages=$derived(remote?.pages??1);
  let entries=$derived(remote?.entries??[]);
  let pageButtons=$derived(directoryPages(page,pages));let liveEnabled=$derived(foreground&&!$isGameRunning);
  let statuses=$derived.by(()=>Object.fromEntries(entries.filter(entry=>entry.online!==null).map(entry=>[entry.id,{address:entry.address,online:entry.online===true,players_online:entry.players_online??0,players_max:entry.players_max??0,version:entry.version,icon:entry.icon??'',motd:entry.motd??[],latency_ms:0,protocol:-1,error:'',checked_at:directoryTimestamp(entry.checked_at),measurement_available:true} as LiveServerStatus])));
  $effect(()=>{const selected={search,mode,version,sort,page,lang:language,region};if(!$isGameRunning)untrack(()=>void loadPublic(selected));else untrack(()=>{request++;loading=false;});});
  async function loadPublic(query={search,mode,version,sort,page,lang:language,region}){if($isGameRunning)return;const generation=++request;loading=true;error='';remote=null;try{const result=await invoke<DirectoryPage>('server_directory_search',{...query,local:false});if(disposed||generation!==request||$isGameRunning)return;if(query.page>result.pages){page=result.pages;return;}remote=result;}catch(problem){if(!disposed&&generation===request&&!$isGameRunning)error=String(problem);}finally{if(!disposed&&generation===request)loading=false;}}
  function commitSearch(){clearTimeout(debounce);search=searchInput.trim();version=versionInput.trim();page=1;remote=null;}
  function scheduleSearch(){clearTimeout(debounce);debounce=setTimeout(commitSearch,450);}
  function resetFilters(){clearTimeout(debounce);searchInput='';search='';versionInput='';version='';mode='';language='';region='';page=1;remote=null;}
  function goto(value:number){if(Number.isFinite(value)){page=Math.max(1,Math.min(pages,Math.floor(value)));jumpPage=page;}}
  async function add(entry:DirectoryEntry){if(adding||busy||saved.has(addressKey(entry.address))||$isGameRunning)return;adding=entry.id;notice='';try{if(await onadd(entry)&&!disposed)notice=entry.name+' se añadió a Mis servidores de esta instalación.';}catch(problem){if(!disposed)error=String(problem);}finally{if(!disposed)adding='';}}
  async function join(entry:DirectoryEntry){if($isGameRunning)return;try{await onjoin(entry.address);}catch(problem){if(!disposed)error=String(problem);}}
  async function copy(address:string){try{await navigator.clipboard.writeText(address);notice='Dirección copiada.';}catch{error='No se pudo copiar la dirección.';}}
  async function measure(entry:DirectoryEntry){if($isGameRunning||pinging[entry.id])return;pinging={...pinging,[entry.id]:true};try{const result=await invoke<Latency>('measure_server_latency',{address:entry.address});if(!disposed&&!$isGameRunning)latencies={...latencies,[entry.id]:result};}catch(problem){if(!disposed&&!$isGameRunning)notice=String(problem);}finally{if(!disposed)pinging={...pinging,[entry.id]:false};}}
  async function openSource(){if(!config.base_url)return;try{await openUrl(config.base_url+'/api/v1/servers');}catch{error='No se pudo abrir la página de TP API.';}}
  async function publish(event:SubmitEvent){event.preventDefault();if(publishing||$isGameRunning)return;publishing=true;error='';notice='';try{const message=await invoke<string>('server_directory_submit',{name:publishName,address:publishAddress,category:publishCategory,region:publishRegion,language:publishLanguage});if(!disposed&&!$isGameRunning){notice=message;publishOpen=false;publishName='';publishAddress='';page=1;await loadPublic();}}catch(problem){if(!disposed&&!$isGameRunning)error=String(problem);}finally{if(!disposed)publishing=false;}}
  const iconFor=(entry:DirectoryEntry)=>entry.tags.some(tag=>['pvp','factions','anarchy'].includes(tag))?'diamond_sword':entry.tags.includes('pixelmon')?'ender_pearl':entry.tags.includes('skyblock')?'grass_block':entry.tags.includes('economy')?'emerald':'compass';
  onMount(()=>{const visibility=()=>foreground=document.visibilityState!=='hidden'&&navigator.onLine!==false;visibility();document.addEventListener('visibilitychange',visibility);window.addEventListener('online',visibility);window.addEventListener('offline',visibility);void invoke<Config>('server_directory_config').then(value=>{if(!disposed)config=value;}).catch(()=>{});const timer=setInterval(()=>{if(foreground&&!$isGameRunning&&!loading)void loadPublic();},60000);return()=>{clearInterval(timer);document.removeEventListener('visibilitychange',visibility);window.removeEventListener('online',visibility);window.removeEventListener('offline',visibility);};});
  onDestroy(()=>{disposed=true;request++;clearTimeout(debounce);});
</script>

<section class="server-directory" aria-labelledby="directory-title">
  <header class="directory-heading"><div><span class="eyebrow">ENCUENTRA TU PRÓXIMA COMUNIDAD</span><h2 id="directory-title">Un mundo para cada forma de jugar</h2><p>Descubre servidores y guarda solo los que quieras en tu propia lista.</p></div><span class="directory-count"><strong>{total.toLocaleString()}</strong><small>en TP API</small></span></header>
  <div class="source-tabs" aria-label="Fuente del catálogo"><span class="api-source"><UiIcon name="globe" size={18}/><strong>TP API</strong><small>Consulta gratuita · directorio público</small></span><button class="publish-toggle" disabled={!config.publishing_available||$isGameRunning} aria-expanded={publishOpen} onclick={()=>publishOpen=!publishOpen}><UiIcon name="plus" size={17}/>Publicar servidor</button></div>
  {#if publishOpen}<form class="publish-form" onsubmit={publish}><header><h3>Publicar un servidor en TP API</h3><p>Tu dirección será pública. TP API comprobará que responde como servidor Java antes de publicarlo.</p></header><div><label>Nombre<input bind:value={publishName} maxlength="120" required placeholder="Nombre de la comunidad"/></label><label>Dirección Java<input bind:value={publishAddress} maxlength="320" required placeholder="play.ejemplo.net:25565"/></label><label>Modalidad<select bind:value={publishCategory}>{#each DIRECTORY_MODES.filter(([id])=>id) as [id,label]}<option value={id==='minigames'?'Minijuegos':id==='mmorpg'?'RPG':id==='anarchy'?'Anarquía':label}>{label}</option>{/each}</select></label><label>Región<select bind:value={publishRegion}>{#each ['Global','LATAM','ES','NA','EU','SA'] as value}<option {value}>{value}</option>{/each}</select></label><label>Idioma<select bind:value={publishLanguage}><option value="ES">Español</option><option value="EN">Inglés</option><option value="PT">Português</option></select></label></div><footer><button type="button" disabled={publishing} onclick={()=>publishOpen=false}>Cancelar</button><button class="primary" disabled={publishing||!publishName.trim()||!publishAddress.trim()}>{publishing?'Comprobando servidor…':'Comprobar y publicar'}</button></footer></form>{/if}
  <form class="directory-filters" onsubmit={event=>{event.preventDefault();commitSearch();}}>
    <label class="search-input"><span>Buscar servidor</span><div><UiIcon name="search" size={17}/><input type="search" placeholder="Nombre, dirección o comunidad…" bind:value={searchInput} oninput={scheduleSearch} maxlength="120"/></div></label>
    <label><span>Modalidad</span><select bind:value={mode} onchange={()=>page=1}>{#each DIRECTORY_MODES as [value,label]}<option {value}>{label}</option>{/each}</select></label>
    <label><span>Idioma</span><select bind:value={language} onchange={()=>page=1}><option value="">Todos</option><option value="ES">Español</option><option value="EN">Inglés</option><option value="PT">Português</option></select></label><label><span>Región declarada</span><select bind:value={region} onchange={()=>page=1}><option value="">Todas</option>{#each ['Global','LATAM','ES','NA','EU','SA'] as value}<option {value}>{value}</option>{/each}</select></label>
    <label><span>Versión de Minecraft</span><input placeholder="Ej. 1.21" bind:value={versionInput} oninput={scheduleSearch} maxlength="32"/></label><label><span>Ordenar por</span><select bind:value={sort} onchange={()=>page=1}><option value="players">Más jugadores</option><option value="newest">Más recientes</option></select></label>
    <button class="filter-submit" type="submit"><UiIcon name="search" size={16}/>Buscar</button>
  </form>
  <div class="live-toolbar"><span class:live={liveEnabled}><i></i>{liveEnabled?'Estado en la nube · consulta de esta página cada 60 s':'Actualización pausada'}</span><button disabled={!entries.length||!liveEnabled||loading} onclick={()=>void loadPublic()}><UiIcon name="refresh" size={15}/>Actualizar página</button></div>
  <div class="source-note"><UiIcon name="info" size={16}/><p>Fuente: TP API{remote?.stale?' · última página guardada':''}. Jugadores, icono y mensaje se consultan en la nube. La fecha de cada tarjeta indica la antigüedad del dato; «Medir ping» realiza una conexión TCP desde tu equipo solo cuando lo pulsas.</p><button disabled={!config.configured} onclick={openSource}>Fuente y API<UiIcon name="external" size={13}/></button></div>
  {#if notice}<p class="directory-notice" role="status">{notice}</p>{/if}
  {#if error}<div class="directory-notice" role="alert"><p>{error}</p><div><button disabled={loading||$isGameRunning} onclick={()=>void loadPublic()}>Reintentar TP API</button></div></div>{/if}
  {#if remote?.stale}<p class="directory-notice" role="status">{remote.message}</p>{/if}
  {#if loading&&!entries.length}<div class="directory-empty" role="status"><UiIcon name="refresh" size={30}/><h3>Buscando comunidades…</h3><p>Cargando la página {page} del catálogo público.</p></div>
  {:else if !entries.length && !error}<div class="directory-empty"><UiIcon name="search" size={32}/><h3>No hay coincidencias con estos filtros</h3><button onclick={resetFilters}>Limpiar filtros</button></div>
  {:else}<div class="directory-grid">{#each entries as entry (entry.id)}
    {@const status=statuses[entry.id]}
    {@const measured=status?.measurement_available===false?undefined:status}
    {@const online=measured?.online??entry.online}
    {@const players=measured?(measured.online?measured.players_online:null):entry.players_online}
    {@const maximum=measured?(measured.online?measured.players_max:null):entry.players_max}
    {@const alreadySaved=saved.has(addressKey(entry.address))}
    <article class="directory-card">
      <div class="card-top"><span class="server-emblem">{#if status?.icon||entry.icon}<img src={status?.icon||entry.icon} alt="" loading="lazy"/>{:else}<GameIcon name={iconFor(entry)} size={32}/>{/if}</span><div><small>{entry.category||entry.tags.slice(0,2).join(' · ')||'Comunidad Minecraft'}</small><h3 data-no-translate>{entry.name}</h3></div>{#if entry.featured&&entry.from_cloud&&directoryTimestamp(entry.featured_until??'')>Date.now()}<span class="selection-label" title="Posición patrocinada activa">PATROCINADO</span>{/if}</div>
      <button class="server-address" onclick={()=>copy(entry.address)} title="Copiar dirección"><span data-no-translate>{entry.address}</span><UiIcon name="copy" size={14}/></button>
      <p class="server-description" data-no-translate>{entry.description||'Descubre sus mundos y su comunidad.'}</p>
      {#if status?.motd?.length}<ServerMotd spans={status.motd} stale={!status.online||remote?.stale}/>{:else}<p class="motd-placeholder">{loading?'Actualizando el mensaje desde la nube…':measured?.online?'Este servidor no publica un mensaje.':'Sin mensaje reciente disponible.'}</p>{/if}
      <div class="card-tags">{#if entry.language}<span>{entry.language==='ES'?'Español':entry.language==='PT'?'Português':entry.language==='EN'?'Inglés':entry.language}</span>{/if}{#if entry.region}<span>{entry.region}</span>{/if}{#if !entry.java_compatible}<span>Bedrock</span>{/if}{#if status?.version||entry.version}<span data-no-translate title={status?.version||entry.version}>{status?.version||entry.version}</span>{/if}</div>
      <div class="server-presence"><span class:online={online===true&&!status?.refresh_error} class:offline={online===false}><i></i>{pinging[entry.id]?'Actualizando…':status?.refresh_error?'Sin actualización':online===null?'Estado sin consultar':online?'En línea':'Sin respuesta'}</span><strong>{players===null?'— jugadores':`${players.toLocaleString()} / ${(maximum??0).toLocaleString()} jugadores`}</strong></div>
      {#if measured?.checked_at}<small class="status-time">Última consulta en la nube · {new Date(measured.checked_at).toLocaleString()}</small>{/if}
      {#if latencies[entry.id]}<div class="client-latency" class:good={latencies[entry.id].quality==='good'} class:fair={latencies[entry.id].quality==='fair'} class:poor={latencies[entry.id].quality==='poor'}><i></i>Desde tu PC: <strong>{latencies[entry.id].latency_ms} ms</strong><small>{new Date(latencies[entry.id].checked_at).toLocaleTimeString()}</small></div>{/if}
      <div class="card-actions"><button class="primary" disabled={!entry.java_compatible||$isGameRunning||loading} title={entry.java_compatible?`Usará tu instalación ${currentVersion}`:'Este servidor solo declara soporte Bedrock'} onclick={()=>void join(entry)}><UiIcon name="play" size={16}/>Entrada rápida</button><button disabled={busy||!!adding||alreadySaved||!entry.java_compatible||$isGameRunning||loading} onclick={()=>void add(entry)}><UiIcon name={alreadySaved?'check':'plus'} size={15}/>{alreadySaved?'Guardado':adding===entry.id?'Guardando…':'Añadir'}</button><button class="ping-button" disabled={pinging[entry.id]||!entry.java_compatible||!liveEnabled} title="Medir tiempo de conexión TCP desde tu PC" aria-label={`Medir ping de ${entry.name}`} onclick={()=>void measure(entry)}><UiIcon name="refresh" size={15}/>{pinging[entry.id]?'Midiendo…':'Medir ping'}</button></div>
    </article>
  {/each}</div>{/if}
  {#if pages>1 && !error}<nav class="directory-pagination" aria-label="Páginas del catálogo"><button disabled={page<=1||loading} onclick={()=>goto(page-1)}><UiIcon name="left" size={14}/>Anterior</button>{#each pageButtons as value,index}{#if index>0 && value>pageButtons[index-1]+1}<span>…</span>{/if}<button class:active={value===page} aria-current={value===page?'page':undefined} disabled={loading} onclick={()=>goto(value)}>{value}</button>{/each}<button disabled={page>=pages||loading} onclick={()=>goto(page+1)}>Siguiente<UiIcon name="arrow" size={14}/></button><form onsubmit={event=>{event.preventDefault();goto(jumpPage);}}><label>Ir a<input type="number" min="1" max={pages} bind:value={jumpPage}/></label><button disabled={loading}>Ir</button></form></nav>{/if}
  <footer><p>TP API es un catálogo público de consulta gratuita, sujeto a disponibilidad y límites de uso. Si no responde, solo se puede mostrar una página anterior guardada de TP API, identificada como tal. No existe un registro universal de todos los servidores.</p><small>Se añaden a <strong>Mis servidores</strong> únicamente cuando tú lo eliges.</small></footer>
</section>

<style>
