  .publish-toggle{margin-left:auto}.publish-form{padding:20px;border:1px solid rgba(var(--primary-rgb),.25);background:#0003;display:grid;gap:16px}.publish-form>div{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:13px}.publish-form label{display:grid;gap:8px;font-size:.67rem;color:#afa2c1}.publish-form input,.publish-form select{background:#0b0b0f;border:1px solid #3c304d;color:#eae1f4;font:inherit;padding:10px;min-width:0;width:100%;box-sizing:border-box;color-scheme:dark}.publish-form footer{display:flex;justify-content:flex-end;gap:9px}.client-latency{display:flex;gap:7px;align-items:center;font-size:.68rem}.client-latency i{width:6px;height:6px;background:currentColor}.client-latency.good{color:#79cba8}.client-latency.fair{color:#e0c777}.client-latency.poor{color:#df999b}.client-latency small{margin-left:auto}.directory-filters{grid-template-columns:repeat(4,minmax(100px,1fr))!important}.search-input{grid-column:span 2}@media(max-width:1000px){.directory-filters{grid-template-columns:repeat(2,minmax(100px,1fr))!important}.filter-submit{grid-column:auto!important}.publish-toggle{margin-left:0}}

  .live-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.live-toolbar>span{display:flex;align-items:center;gap:8px;font-size:.67rem;color:#91a2bb}.live-toolbar>span.live{color:#82cdb1}.live-toolbar i{width:6px;height:6px;background:currentColor;flex-shrink:0}.motd-placeholder{padding:10px;border:1px dashed #ffffff13;background:#0002;min-height:2.4em;font-size:.66rem;color:#8093ad}.server-presence>strong{font-size:.72rem;color:#dae7f4;font-weight:600}
  .server-directory{display:grid;gap:18px;min-width:0;color:var(--text,#e7eaf4)}
  .directory-heading{display:flex;align-items:center;justify-content:space-between;gap:20px}.eyebrow{font-size:.58rem;letter-spacing:.12em;color:var(--primary,#c084fc);font-weight:700}h2{font-size:1.35rem;margin:9px 0}h3{font-size:.92rem;margin:4px 0;overflow-wrap:anywhere}p{font-size:.79rem;line-height:1.7;color:#a1afc5;margin:0}small{font-size:.64rem;color:#91a2bb;line-height:1.6}.directory-count{text-align:right;white-space:nowrap}.directory-count strong{display:block;color:var(--primary,#c084fc);font-size:1.8rem}.directory-count small{display:block}
  button{display:inline-flex;align-items:center;justify-content:center;gap:7px;padding:9px 12px;font:inherit;font-size:.74rem;color:#dbe5f4;border:1px solid #ffffff22;background:#090f20aa;cursor:pointer;border-radius:4px}button:hover:not(:disabled){border-color:var(--primary,#c084fc);background:rgba(var(--primary-rgb),.12)}button:disabled{opacity:.45;cursor:default}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--primary,#c084fc);outline-offset:3px}.source-tabs{display:flex;gap:9px;flex-wrap:wrap}.source-tabs button{padding:11px 15px}.source-tabs small{margin-left:4px}.active,.primary{border-color:var(--primary,#c084fc);background:rgba(var(--primary-rgb),.16);color:var(--primary,#d8b4fe)}
  .directory-filters{display:grid;grid-template-columns:minmax(180px,2fr) repeat(3,minmax(100px,1fr)) auto;gap:12px;padding:18px;border:1px solid #ffffff16;background:#080d1d99}.directory-filters label{display:grid;gap:7px;font-size:.64rem;color:#a3b4ca}.directory-filters input,.directory-filters select{box-sizing:border-box;min-width:0;width:100%;background:#0a1022;color:#dbe4f3;border:1px solid #ffffff24;padding:10px;border-radius:3px;font:inherit;font-size:.75rem;color-scheme:dark}.search-input>div{display:flex;align-items:center;gap:8px;background:#0a1022;padding-left:10px;border:1px solid #ffffff24}.search-input input{border:0}.filter-submit{align-self:end;min-height:37px}.source-note{display:flex;align-items:start;gap:10px}.source-note p{font-size:.7rem;flex:1}.source-note :global(svg){flex-shrink:0}.source-note button{border:0;background:none;font-size:.65rem;padding:0;white-space:nowrap}
  .directory-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.directory-card{min-width:0;display:flex;flex-direction:column;gap:12px;padding:18px;border:1px solid rgba(var(--primary-rgb),.22);background:linear-gradient(145deg,rgba(var(--bg-base-rgb,12,14,24),.84),rgba(var(--bg-base-rgb,12,14,24),.68));box-shadow:inset 0 2px #ffffff08,0 3px #0004}.card-top{display:flex;align-items:center;gap:11px;position:relative}.card-top>div{flex:1;min-width:0}.server-emblem{width:50px;height:50px;display:grid;place-items:center;flex-shrink:0;border:1px solid #ffffff18;background:#0004}.server-emblem img{width:100%;height:100%;object-fit:contain;image-rendering:pixelated}.card-top small{font-size:.56rem;text-transform:uppercase;letter-spacing:.04em}.selection-label{align-self:start;font-size:.44rem;color:var(--primary,#c084fc);letter-spacing:.05em;white-space:nowrap}.server-address{width:100%;text-align:left;justify-content:space-between;background:#0002;padding:8px;font-size:.7rem;color:#adbcd4}.server-address span{overflow-wrap:anywhere;min-width:0}.server-address :global(svg){flex-shrink:0}.server-description{font-size:.73rem;min-height:2.8em;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;line-clamp:2;overflow:hidden}.card-tags{display:flex;gap:5px;flex-wrap:wrap}.card-tags span{padding:3px 6px;border:1px solid #ffffff13;font-size:.57rem;color:#9faec8;overflow:hidden;max-width:100%;white-space:nowrap;text-overflow:ellipsis}.server-presence{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:auto}.server-presence>span{display:flex;align-items:center;gap:6px;font-size:.61rem;color:#8fa0b8}.server-presence i{width:5px;height:5px;background:currentColor}.server-presence .online{color:#7dd3b2}.server-presence .offline{color:#b4a1aa}.status-time{font-size:.55rem}.card-actions{display:flex;gap:7px;flex-wrap:wrap;padding-top:4px}.card-actions .primary{flex:1}.card-actions button{font-size:.67rem;padding:8px}.card-actions .ping-button{flex:0}.directory-notice{border:1px solid #bda16d44;background:#bda16d0b;padding:13px 16px;color:#d8c8a7;font-size:.76rem;line-height:1.7}.directory-notice>div{display:flex;gap:8px;margin-top:10px}.directory-empty{display:flex;align-items:center;justify-content:center;gap:13px;flex-direction:column;min-height:220px;padding:20px;text-align:center;border:1px dashed #ffffff20}.directory-empty :global(svg){color:var(--primary,#c084fc)}
